import{_ as e,c as p,a2 as a,o}from"./chunks/framework.CqbvlPrP.js";const m=JSON.parse('{"title":"交易需要过三关","description":"","frontmatter":{},"headers":[],"relativePath":"stock/交易认知/交易三关.md","filePath":"stock/交易认知/交易三关.md"}'),r={name:"stock/交易认知/交易三关.md"};function s(n,t,c,i,d,l){return o(),p("div",null,t[0]||(t[0]=[a('<h1 id="交易需要过三关" tabindex="-1">交易需要过三关 <a class="header-anchor" href="#交易需要过三关" aria-label="Permalink to &quot;交易需要过三关&quot;">​</a></h1><p>做交易需要过三关，很多人连第一关都过不去就已经放弃了，更不用谈后面的说辞了。</p><p>三关分为:技术关，资金关，心态关。</p><p>这三关必须全过才可以在交易市场游刃有余，但凡有一关有问题最终都会血本无归。</p><p>第一关:技术关。</p><p>大部分人在这一关就已经躺枪了，很多技术似是而非，这个技术赚钱，过一阵变成了赔钱。看了好几年书籍发现没有一个技术是万能的，都是在赔钱与赚钱之间游荡，大部分人在这一阶段根本走不出来，赔的万念俱灰的时候彻底的离开了这个市场，最后总结出这是个赌场根本不可能赚钱。能走出来的人会发现技术就是工具而已，工具顺不顺手跟自己的性格有莫大的关系，任何技术都可以赚钱，也都可以赔钱，关键在于什么时候使用什么技术，什么时候很重要，这个需要多年的实战经验才可以总结出来，不是看几本书就可以的，是需要实践的。这个技术阶段走出来的人基本都是可以挣到钱了但是有时候也会赔钱这就涉及到第二关资金管理了。</p><p>第二关:资金关。</p><p>第一关走出来的人已经深刻认识到这个市场是可以挣钱的。但是不够稳定有时候会赔的很多原因在于资金管理不到位。很多人觉得自己技术很牛逼了，曾经有些行情看的非常准，十次看对了八次。每次都是小资金上。觉得来钱慢，于是乎重仓一把，结果这次看错了资金大幅度回撤，让自己几年挣的钱在一夕之间化为乌有。然后左思右想到底哪里出了问题，其实说白了就是资金管理不到位。觉得自己技术牛逼了 可以甩开膀子大干一场，结果错了。等回头一想发现原来是自己重仓的原因导致资金回撤非常厉害。针对此关利弗莫尔总结了一句非常经典的名言:没有百分百有效的交易规则，一定不要孤注一掷。这一关过了之后就来到交易世界的最后一关也是最难的一关。心态关也可以说成是人性关。</p><p>第三关:心态关。</p><p>来到这一关的人已经是凤毛麟角了。基本能挣点钱了但是不稳定。技术有了，资金管理也到位了。我还缺啥呢，心态。人的心态每时每刻都在发生变化。当账户挣钱的时候觉得自己天下无敌。当账户赔钱的时候觉得自己是这个世界上最蠢的人。这一关跟聪不聪明没啥关系，只跟你的心态有关。你说你聪明但你的心理极度脆弱，一赔钱就脑子犯晕。一挣钱就狂妄自大，目无一切。如此几个回合下来再聪明的脑子也被弄成神经兮兮了。这一关难度最大，走出来的人才是最后的赢家，走不出来的人直到死亡也走不出来。</p><p>心态关跟你看多少书做多少年交易已经没关系了，只跟你的内心有关系。看看古往今来成大事的人哪个心态不好，刘邦，朱元璋，毛主席。心态极好的人才能成就一番伟业。</p><p>最后总结:这个市场不适合普通人，普通人的心态都是极度脆弱的，经不起惊涛骇浪。</p>',12)]))}const f=e(r,[["render",s]]);export{m as __pageData,f as default};
